 import unittest
from candidate import fruit_distribution

class TestFruitDistribution(unittest.TestCase):
    def test_normalcase(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_empty_input(self):
        self.assertEqual(fruit_distribution("", 10), 10)

    def test_none_input(self):
        self.assertEqual(fruit_distribution(None, 10), 10)

    def test_invalid_input(self):
        self.assertRaises(ValueError, fruit_distribution, "invalid input", 10)

    def test_negative_input(self):
        self.assertRaises(ValueError, fruit_distribution, "-5 apples and -6 oranges", 19)

    def test_all_fruits_are_apples_or_oranges(self):
        self.assertEqual(fruit_distribution("100 apples and 0 oranges", 120), 20)

    def test_mango_fruits_are_zero(self):
        self.assertEqual(fruit_distribution("0 apples and 0 oranges", 10), 10)

    def test_only_mango_fruits(self):
        self.assertEqual(fruit_distribution("1 mango and 0 apples and 0 oranges", 1), 1)

    def test_integer_input(self):
        self.assertEqual(fruit_distribution("0", 1), 1)

    def test_string_with_only_fruits(self):
        self.assertEqual(fruit_distribution("apples oranges", 0), 0)

    def test_empty_number_string(self):
        self.assertEqual(fruit_distribution(" apples and  ", 10), 10)

    def test_all_non_digit_input(self):
        self.assertRaises(ValueError, fruit_distribution, "a apples and b oranges", 10)

    def test_fruit_distribution_with_floats(self):
        self.assertRaises(ValueError, fruit_distribution, "1.5 apples and 2.5 oranges", 5)

if __name__ == '__main__':
    unittest.main()
